-- Stage B3 — 27 more curated anchor terms for the git-cli path
-- All difficulty 1, all curated, reviewed 2026-05-04.
-- Voice matches the git-commit template above.
-- Local seed equivalent of supabase/migrations/20260504090000_more_anchors_git_cli.sql.
-- ────────────────────────────────────────────────────────────

insert into terms (
  id, term, pronunciation, path, difficulty,
  one_line_definition, long_definition, example_in_sentence, why_it_matters,
  related_terms, prerequisites, stretch_term,
  multiple_choice_distractors, fill_in_blank_sentence, use_in_sentence_prompt,
  source, reviewed_by, reviewed_at
) values

-- ─── git-cli: git verbs (16) ──────────────────────────────────
('git-branch', 'branch', null, 'git-cli', 1,
 'A separate line of development that lets you work on changes without touching the main code.',
 'A branch is a movable pointer to a series of commits. You start a branch off the main code, do whatever experimental or in-progress work you want, and the main branch stays untouched until you decide to merge. Most teams keep one long-lived main branch and spin off short-lived feature branches.',
 'I''ll spin up a branch for the new login flow so I don''t break anything on main.',
 'Claude Code constantly creates branches before risky work. When dev family says "what branch are you on?" they''re asking which parallel line of work you''re editing — knowing the term means you can answer without scrambling.',
 ARRAY['git-commit','git-merge','git-checkout']::text[],
 ARRAY['git-commit']::text[],
 'git-rebase',
 ARRAY[
   'A backup copy of the entire repository',
   'A tag marking a released version of the code',
   'A folder inside a project that holds related files'
 ]::text[],
 'I''ll spin up a ___ for the new login flow so I don''t break anything on main.',
 'Use ''branch'' in a sentence about working on a feature without disturbing the main code.',
 'curated', 'curator', '2026-05-04'),

('git-merge', 'merge', null, 'git-cli', 1,
 'Combining the changes from one branch into another, usually pulling a feature into main.',
 'A merge takes the work from one branch and folds it into another, creating a merge commit that ties the two histories together. If both branches changed the same lines in different ways, you get a merge conflict you have to resolve by hand before the merge completes.',
 'Once the PR is approved I''ll merge it into main and delete the branch.',
 'Every PR ends in a merge. Knowing what merge means closes the loop on the whole branch → commit → push → PR → merge cycle that Claude Code runs through every working session.',
 ARRAY['git-branch','git-pr','git-conflict']::text[],
 ARRAY['git-branch','git-commit']::text[],
 'git-rebase',
 ARRAY[
   'Deleting a branch you no longer need',
   'Copying a repository onto your own machine',
   'Renaming a file in version control'
 ]::text[],
 'Once the PR is approved I''ll ___ it into main and delete the branch.',
 'Use ''merge'' in a sentence about combining a finished feature branch into the main code.',
 'curated', 'curator', '2026-05-04'),

('git-pull', 'pull', null, 'git-cli', 1,
 'Downloading the latest commits from a remote and folding them into your current branch.',
 'A pull is really two operations stitched together: it fetches the new commits from the remote, then merges them into the branch you''re on. It''s how you get up to date with whatever your teammates (or your other laptop) have pushed since you last synced.',
 'Pull before you start working — main moved a lot since yesterday.',
 'When your other machine is missing the latest, the answer is almost always "I forgot to pull." This is the receiving end of push, and getting fluent in the pair makes sync conversations land.',
 ARRAY['git-push','git-fetch','git-merge']::text[],
 ARRAY['git-commit','git-push']::text[],
 null,
 ARRAY[
   'Deleting all uncommitted changes in a working directory',
   'Reverting the most recent commit',
   'Asking a teammate to review your code'
 ]::text[],
 '___ before you start working — main moved a lot since yesterday.',
 'Use ''pull'' in a sentence about getting your local copy up to date with a remote.',
 'curated', 'curator', '2026-05-04'),

('git-fetch', 'fetch', null, 'git-cli', 1,
 'Downloading new commits from a remote without merging them into your branch yet.',
 'A fetch grabs the latest history from the remote and updates your local view of what''s on the remote — but it does NOT touch the branch you''re working on. It''s the safer cousin of pull: you can see what changed before deciding to merge.',
 'Let me fetch first so I can see what landed on main before I rebase.',
 'When Claude Code says "fetching origin" in a status line, this is what''s happening. Knowing the difference between fetch (download only) and pull (download + merge) keeps you out of accidental-merge trouble.',
 ARRAY['git-pull','git-remote','git-merge']::text[],
 ARRAY['git-commit']::text[],
 'git-rebase',
 ARRAY[
   'Combining two branches into one',
   'Saving uncommitted changes to a temporary stack',
   'Creating a new branch from the current commit'
 ]::text[],
 'Let me ___ first so I can see what landed on main before I rebase.',
 'Use ''fetch'' in a sentence about checking what changed on a remote before merging.',
 'curated', 'curator', '2026-05-04'),

('git-clone', 'clone', null, 'git-cli', 1,
 'Downloading a full copy of a remote repository onto your machine for the first time.',
 'A clone pulls down the entire history of a repo — every commit, every branch — and sets up the remote pointer so future pushes and pulls know where to go. It''s how you start working on a project you didn''t create yourself.',
 'I cloned the repo last night but I haven''t opened it in the editor yet.',
 'Every new project starts with a clone. When dev family says "just clone the repo," they mean run one command and the whole codebase lands on your laptop, history and all.',
 ARRAY['git-fork','git-remote','git-pull']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'Creating a new branch off the current commit',
   'Making a backup copy of a single file',
   'Forking a repo into your own GitHub account'
 ]::text[],
 'I ___ the repo last night but I haven''t opened it in the editor yet.',
 'Use ''clone'' in a sentence about getting a project onto your machine for the first time.',
 'curated', 'curator', '2026-05-04'),

('git-fork', 'fork', null, 'git-cli', 1,
 'Making your own server-side copy of someone else''s repo, usually so you can change it independently.',
 'A fork lives on a hosting service like GitHub — it''s a full copy of a repo under your account, with its own URL and its own permissions. You typically fork a project you don''t have write access to, make changes in your fork, then open a PR back to the original.',
 'I forked the open-source library so I could patch the bug and send a PR upstream.',
 'Open-source contributions almost always start with a fork. When dev family talks about "sending a fix upstream," the fork is what they used to make the change in the first place.',
 ARRAY['git-clone','git-pr','git-remote']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A local branch off the main line of development',
   'A snapshot saved before a risky operation',
   'A duplicate file with a slightly different name'
 ]::text[],
 'I ___ the open-source library so I could patch the bug and send a PR upstream.',
 'Use ''fork'' in a sentence about making your own copy of someone else''s project.',
 'curated', 'curator', '2026-05-04'),

('git-diff', 'diff', null, 'git-cli', 1,
 'A line-by-line view of what changed between two versions of code.',
 'A diff shows what was added, removed, or modified between two snapshots — usually your working changes versus the last commit, or one commit versus another. Lines starting with `+` are additions, `-` are removals. It''s the universal format for reviewing code changes.',
 'Take a quick look at the diff before I commit — I want a second pair of eyes on the regex.',
 'Every code review is a diff review. When Claude Code says "here''s the diff" before applying a change, knowing the term means you can read the proposal instead of bracing for a surprise.',
 ARRAY['git-commit','git-pr','git-log']::text[],
 ARRAY['git-commit']::text[],
 null,
 ARRAY[
   'A list of files in a directory',
   'A backup of the repository before a merge',
   'A configuration file describing build steps'
 ]::text[],
 'Take a quick look at the ___ before I commit — I want a second pair of eyes on the regex.',
 'Use ''diff'' in a sentence about reviewing what changed in some code.',
 'curated', 'curator', '2026-05-04'),

('git-stash', 'stash', null, 'git-cli', 1,
 'Tucking your in-progress changes into a temporary stack so you can switch contexts without committing.',
 'A stash captures everything you''ve modified but not yet committed and stores it aside, leaving your working directory clean. You can switch branches, do something urgent, then pop the stash back to resume exactly where you left off.',
 'Let me stash this real quick — I need to switch branches and look at the bug report.',
 'Stash is the "hold this for a sec" of Git. When Claude Code or a teammate says "I stashed it," they paused work without losing it — knowing the term means you understand mid-task context switches.',
 ARRAY['git-branch','git-checkout','git-commit']::text[],
 ARRAY['git-commit','git-branch']::text[],
 null,
 ARRAY[
   'Permanently deleting your uncommitted changes',
   'Pushing your work to a private remote',
   'Tagging the current commit with a version number'
 ]::text[],
 'Let me ___ this real quick — I need to switch branches and look at the bug report.',
 'Use ''stash'' in a sentence about temporarily setting aside in-progress work.',
 'curated', 'curator', '2026-05-04'),

('git-log', 'log', null, 'git-cli', 1,
 'The chronological list of commits on a branch, with messages, authors, and timestamps.',
 'The log is the project''s memory. Each entry shows who committed what, when, and the message they wrote. You scroll through it to see how a piece of code got the way it is, or to find the commit where something broke.',
 'Check the log — I want to see who last touched the auth code.',
 'When something mysteriously broke, the log is where you investigate. Hearing "let me check the log" or "git log says..." in a debugging session means someone is reading the project''s history.',
 ARRAY['git-commit','git-diff','git-head']::text[],
 ARRAY['git-commit']::text[],
 null,
 ARRAY[
   'A file recording errors at runtime',
   'A list of currently open branches',
   'A queue of pending pull requests'
 ]::text[],
 'Check the ___ — I want to see who last touched the auth code.',
 'Use ''log'' in a sentence about looking through a project''s commit history.',
 'curated', 'curator', '2026-05-04'),

('git-rebase', 'rebase', 'REE-base', 'git-cli', 1,
 'Replaying your branch''s commits on top of a newer version of another branch to get a clean history.',
 'A rebase rewinds your commits, updates your branch to start from the latest tip of (usually) main, then re-applies your commits one at a time on top. The result is a linear history with no merge commit — like you''d started your branch from the up-to-date code in the first place.',
 'I''m going to rebase onto main before opening the PR so the history stays clean.',
 'Rebase is one of the words you''ll hear constantly in Claude Code sessions and from dev family. It''s the cleaner alternative to merging in updates from main, and knowing the term unlocks a whole layer of "history hygiene" conversations.',
 ARRAY['git-merge','git-branch','git-conflict']::text[],
 ARRAY['git-commit','git-branch','git-merge']::text[],
 null,
 ARRAY[
   'Resetting your branch back to a previous commit',
   'Renaming a branch on the remote',
   'Squashing several commits into one'
 ]::text[],
 'I''m going to ___ onto main before opening the PR so the history stays clean.',
 'Use ''rebase'' in a sentence about updating your branch with the latest changes from main.',
 'curated', 'curator', '2026-05-04'),

('git-conflict', 'merge conflict', null, 'git-cli', 1,
 'When two branches changed the same lines in different ways, forcing you to pick which version wins.',
 'A merge conflict happens when Git can''t automatically reconcile two sets of changes — say, you and a teammate both edited the same function. Git marks the conflicting lines with `<<<<<<<` and `>>>>>>>` and waits for you to decide what the final code should look like, then commit the resolution.',
 'I hit a merge conflict in the auth file — give me 10 minutes to sort it out.',
 'Conflicts are unavoidable on any team. When Claude Code or dev family says "I''m resolving conflicts," knowing what that means saves you from picturing literal arguments.',
 ARRAY['git-merge','git-rebase','git-branch']::text[],
 ARRAY['git-merge','git-branch']::text[],
 null,
 ARRAY[
   'A bug introduced by combining two pieces of code',
   'A permission error when pushing to a remote',
   'A test that fails after a rebase'
 ]::text[],
 'I hit a ___ in the auth file — give me 10 minutes to sort it out.',
 'Use ''merge conflict'' in a sentence about Git not knowing how to combine two sets of edits.',
 'curated', 'curator', '2026-05-04'),

('git-remote', 'remote', null, 'git-cli', 1,
 'A named pointer to a copy of your repository hosted somewhere else — usually GitHub.',
 'A remote is just a URL with a nickname. Most repos have one called `origin` (the place you cloned from). You push to and pull from remotes — they''re how your local repo stays in sync with the team''s shared copy and with services like GitHub.',
 'I added a second remote pointing at the fork so I can push to both places.',
 'When Claude Code says "pushing to remote" or dev family asks "is it on the remote yet?" this is the named server-side copy they mean. Knowing the term separates "saved locally" from "available to others."',
 ARRAY['git-origin','git-push','git-fetch']::text[],
 ARRAY['git-clone']::text[],
 null,
 ARRAY[
   'A branch that has not yet been merged',
   'A folder synced via a cloud-storage service',
   'A computer used to access a server over SSH'
 ]::text[],
 'I added a second ___ pointing at the fork so I can push to both places.',
 'Use ''remote'' in a sentence about a server-side copy of your repository.',
 'curated', 'curator', '2026-05-04'),

('git-origin', 'origin', null, 'git-cli', 1,
 'The default name Git gives to the remote you originally cloned from.',
 '`origin` isn''t magic — it''s just the conventional nickname Git assigns to the first remote you set up. When you `git push` with no arguments, you''re pushing to origin. Repos can have other remotes too, but origin is almost always the team''s canonical copy.',
 'Push to origin when you''re ready and I''ll pull it down on the laptop.',
 'You''ll see "origin/main" in Claude Code output and in tutorials constantly. It just means "the main branch as it exists on the place I cloned from" — once that clicks, half the Git output reads cleaner.',
 ARRAY['git-remote','git-push','git-pull']::text[],
 ARRAY['git-clone','git-remote']::text[],
 null,
 ARRAY[
   'The first commit ever made in a repository',
   'The branch a feature was originally created from',
   'The user who first opened a pull request'
 ]::text[],
 'Push to ___ when you''re ready and I''ll pull it down on the laptop.',
 'Use ''origin'' in a sentence about the default remote of your repository.',
 'curated', 'curator', '2026-05-04'),

('git-head', 'HEAD', 'head', 'git-cli', 1,
 'A pointer to the commit you''re currently sitting on — usually the tip of your active branch.',
 'HEAD is Git''s way of saying "you are here." It points to the latest commit on your current branch most of the time, but if you check out a specific commit by hash, HEAD points there instead (a state called "detached HEAD"). Most Git commands are implicitly about HEAD.',
 'If you reset to HEAD~1 you''ll move back one commit — make sure you stash first.',
 'HEAD shows up in nearly every Git error message and tutorial. Knowing it''s just "where you are right now" makes a lot of cryptic-looking output suddenly readable.',
 ARRAY['git-commit','git-branch','git-checkout']::text[],
 ARRAY['git-commit','git-branch']::text[],
 null,
 ARRAY[
   'The first commit in the repository',
   'The maintainer of the main branch',
   'The header section of a configuration file'
 ]::text[],
 'If you reset to ___~1 you''ll move back one commit — make sure you stash first.',
 'Use ''HEAD'' in a sentence about the commit you''re currently checked out on.',
 'curated', 'curator', '2026-05-04'),

('git-tag', 'tag', null, 'git-cli', 1,
 'A permanent label attached to a specific commit, usually to mark a released version.',
 'A tag is like a sticky note on a commit — it doesn''t move when new commits land. Most teams tag release commits with a version number (`v1.0.0`, `v1.0.1`) so they can always jump back to exactly the code that shipped.',
 'Tag this commit v1.0.0 so we can roll back to it if the deploy goes sideways.',
 'When dev family talks about "the v2.3 tag" or Claude Code says "tagged release," this is the marker they mean. Tags are how versions stay findable in a project''s history forever.',
 ARRAY['git-commit','git-log','dev-deploy']::text[],
 ARRAY['git-commit']::text[],
 null,
 ARRAY[
   'A label applied to a pull request to categorize it',
   'A keyword embedded in a commit message',
   'A user mentioned in a code-review comment'
 ]::text[],
 'Add a ___ on this commit, v1.0.0, so we can roll back to it if the deploy goes sideways.',
 'Use ''tag'' in a sentence about marking a release in your project history.',
 'curated', 'curator', '2026-05-04'),

('git-checkout', 'checkout', null, 'git-cli', 1,
 'Switching the files in your working directory to match a different branch or commit.',
 '`git checkout` moves you between snapshots — to another branch, to a specific commit, or even just to restore a single file to a previous state. (Newer Git also offers `git switch` and `git restore` for these jobs separately, but checkout is still everywhere in tutorials and old habits.)',
 'Checkout the feature branch and tell me if the bug repros there too.',
 'You hear "checkout" in nearly every Git conversation. Knowing it''s how you change which version of the code you''re looking at unlocks the entire branch-switching workflow.',
 ARRAY['git-branch','git-head','git-stash']::text[],
 ARRAY['git-branch']::text[],
 null,
 ARRAY[
   'Logging out of your Git account on a remote',
   'Marking a pull request as ready for review',
   'Downloading a release from a hosting service'
 ]::text[],
 '___ the feature branch and tell me if the bug repros there too.',
 'Use ''checkout'' in a sentence about switching to a different branch.',
 'curated', 'curator', '2026-05-04'),

-- ─── git-cli: terminal / shell (11) ───────────────────────────
('cli-terminal', 'terminal', null, 'git-cli', 1,
 'The text-based window where you type commands directly to your computer.',
 'A terminal is the application that gives you a text prompt — Terminal.app on macOS, iTerm, Windows Terminal. You type a command, hit enter, and the computer runs it and prints the output. Underneath the terminal is a shell (like bash or zsh) that actually interprets what you typed.',
 'Open a new terminal tab and run the dev server there so the build keeps going.',
 'Claude Code lives in the terminal. Every "type this in your terminal" instruction assumes you know what one is — having the word locked makes you fluent in any tutorial.',
 ARRAY['cli-bash','cli-cd','cc-claude-code']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A graphical file browser like Finder',
   'A web browser tab used for development',
   'A monitor connected to a remote server'
 ]::text[],
 'Open a new ___ tab and run the dev server there so the build keeps going.',
 'Use ''terminal'' in a sentence about where you type commands on your computer.',
 'curated', 'curator', '2026-05-04'),

('cli-bash', 'bash', null, 'git-cli', 1,
 'A common shell program that interprets the commands you type in a terminal.',
 'Bash (Bourne Again SHell) is the default shell on most Linux servers and was the default on macOS until 2019, when Apple switched to zsh. They''re close cousins — most commands work the same in both. When someone says "run this in bash," they almost always just mean "run this in your terminal."',
 'That install script is bash, so it should work on the Mac without any tweaks.',
 'Tutorials, deploy scripts, and Claude Code instructions are written for bash by default. Knowing the term means you can tell when something needs a real shell vs. a Windows-flavored alternative.',
 ARRAY['cli-terminal','cli-cd','cli-pipe']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A programming language used for web backends',
   'A package manager for installing developer tools',
   'A graphical text editor for code'
 ]::text[],
 'That install script is ___, so it should work on the Mac without any tweaks.',
 'Use ''bash'' in a sentence about the shell program running your commands.',
 'curated', 'curator', '2026-05-04'),

('cli-cd', 'cd', 'C-D', 'git-cli', 1,
 'The command that changes which folder your terminal is currently working in.',
 '`cd` stands for "change directory." You give it a path — `cd src`, `cd ..` to go up one level, `cd ~` for your home folder — and your terminal session moves there. Almost every other command (`ls`, `cat`, `git`) operates on whatever folder you''re currently `cd`''d into.',
 'cd into the project folder before you run npm install or it''ll grab the wrong package.json.',
 'Every multi-step terminal walkthrough starts with `cd somewhere`. Recognizing it on sight means you''re never confused about why a command failed because Claude Code was in the wrong folder.',
 ARRAY['cli-terminal','cli-ls','cli-bash']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A command that copies files between folders',
   'A command that prints the current date',
   'A command that creates a new directory'
 ]::text[],
 '___ into the project folder before you run npm install or it''ll grab the wrong package.json.',
 'Use ''cd'' in a sentence about moving to a different folder in the terminal.',
 'curated', 'curator', '2026-05-04'),

('cli-ls', 'ls', 'L-S', 'git-cli', 1,
 'The command that lists the files and folders in your current directory.',
 '`ls` is short for "list." Run by itself it prints the names of everything in the current folder. Common flags: `ls -a` shows hidden files (the ones that start with a dot), `ls -l` shows sizes and permissions in a long format.',
 'ls the build folder and make sure the assets actually got copied over.',
 'Every terminal session starts with figuring out what''s here. Knowing `ls` means you can verify Claude Code put the right files in the right place without reaching for Finder.',
 ARRAY['cli-cd','cli-cat','cli-terminal']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A command that opens a file in an editor',
   'A command that searches for text in files',
   'A command that deletes a file'
 ]::text[],
 '___ the build folder and make sure the assets actually got copied over.',
 'Use ''ls'' in a sentence about checking what''s inside a folder from the terminal.',
 'curated', 'curator', '2026-05-04'),

('cli-grep', 'grep', null, 'git-cli', 1,
 'A command that searches for a pattern of text inside files and prints the matching lines.',
 '`grep` takes a pattern and one or more files (or piped input) and shows you every line that matches. It''s the default tool for "find me everywhere this string appears." Add `-r` to recurse into folders, `-i` to ignore case, `-n` to show line numbers.',
 'grep for the API key in the codebase to make sure it isn''t hardcoded anywhere.',
 'You''ll see grep in nearly every debug session. When Claude Code says "let me grep the repo for that," knowing the verb means you understand it''s doing a fast text search across files.',
 ARRAY['cli-cat','cli-pipe','cli-bash']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A command that compresses files into an archive',
   'A command that monitors network traffic',
   'A command that sorts lines alphabetically'
 ]::text[],
 '___ for the API key in the codebase to make sure it isn''t hardcoded anywhere.',
 'Use ''grep'' in a sentence about searching for text across files.',
 'curated', 'curator', '2026-05-04'),

('cli-pipe', 'pipe', null, 'git-cli', 1,
 'The `|` character that sends the output of one command into the input of another.',
 'A pipe glues commands together: `ls | grep test` lists the current folder and feeds that list into grep, which prints only the matching lines. Pipes are what makes the terminal feel like Lego — small commands compose into powerful one-liners.',
 'Pipe the log into grep so we only see the error lines.',
 'Pipes are the punctuation of the shell. Once you can read `command-a | command-b | command-c` as "feed a into b into c," half of intimidating-looking terminal commands become legible.',
 ARRAY['cli-grep','cli-bash','cli-cat']::text[],
 ARRAY['cli-terminal','cli-bash']::text[],
 null,
 ARRAY[
   'A command that runs another command with admin privileges',
   'A configuration file that defines build steps',
   'A symbol that comments out a line of code'
 ]::text[],
 '___ the log into grep so we only see the error lines.',
 'Use ''pipe'' in a sentence about chaining two commands together in the terminal.',
 'curated', 'curator', '2026-05-04'),

('cli-sudo', 'sudo', 'SOO-doo', 'git-cli', 1,
 'The command that runs another command with administrator privileges.',
 '`sudo` stands for "superuser do." You prefix any command with it when the action requires elevated permissions — installing system software, editing protected files, restarting services. The terminal will prompt for your password the first time in a session.',
 'You''ll need sudo to install Homebrew on a fresh Mac.',
 'Anytime Claude Code or a tutorial says "run with sudo," there''s a permission gate involved. Knowing the word keeps you from getting stuck on a "permission denied" error.',
 ARRAY['cli-bash','cli-terminal']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A command that suspends a running process',
   'A command that displays the current user''s name',
   'A command that schedules a task to run later'
 ]::text[],
 'You''ll need ___ to install Homebrew on a fresh Mac.',
 'Use ''sudo'' in a sentence about running a command that needs admin permissions.',
 'curated', 'curator', '2026-05-04'),

('cli-cat', 'cat', null, 'git-cli', 1,
 'A command that prints the contents of a file straight to the terminal.',
 '`cat` is short for "concatenate." Give it a filename and it dumps the whole file to your screen. Hand it multiple filenames and it prints them back-to-back. It''s the fastest way to peek at a small text file without opening an editor.',
 'cat the .env file and make sure the Supabase URL is the production one.',
 'When Claude Code or a tutorial says "cat this file to check it," they''re asking you to print it to the terminal. The verb is one of the most-used in any walkthrough.',
 ARRAY['cli-ls','cli-grep','cli-pipe']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A command that creates an empty file',
   'A command that copies a file to a new location',
   'A command that compresses a file'
 ]::text[],
 '___ the .env file and make sure the Supabase URL is the production one.',
 'Use ''cat'' in a sentence about printing a file''s contents to the terminal.',
 'curated', 'curator', '2026-05-04'),

('cli-mv', 'mv', 'M-V', 'git-cli', 1,
 'The command that moves or renames a file or folder.',
 '`mv` is short for "move." `mv old.txt new.txt` renames the file; `mv file.txt subfolder/` moves it into another folder. There''s no separate rename command — renaming is just moving to a new name in the same place.',
 'mv the old config out of the src folder so the build stops picking it up.',
 'Tutorials and Claude Code use mv constantly to rearrange project files. Knowing it covers both move AND rename means you''re not surprised when it shows up in either context.',
 ARRAY['cli-cd','cli-rm','cli-ls']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A command that creates a backup of a file',
   'A command that compares two files line by line',
   'A command that shows the size of a file'
 ]::text[],
 '___ the old config out of the src folder so the build stops picking it up.',
 'Use ''mv'' in a sentence about moving or renaming a file in the terminal.',
 'curated', 'curator', '2026-05-04'),

('cli-rm', 'rm', 'R-M', 'git-cli', 1,
 'The command that deletes a file or folder — permanently, with no trash.',
 '`rm` stands for "remove." `rm file.txt` deletes one file. `rm -r folder/` recursively deletes a folder and everything inside it. There''s no recycle bin: once it''s gone, it''s gone, which is why `rm -rf` (force, recursive) is famous as a command to be careful with.',
 'rm the old build folder before you run a fresh install.',
 'When Claude Code says "I removed the file" or a tutorial says "rm the dist directory," knowing the command keeps you alert that there''s no undo. Critical for following destructive steps without panic.',
 ARRAY['cli-mv','cli-ls','cli-cd']::text[],
 ARRAY['cli-terminal']::text[],
 null,
 ARRAY[
   'A command that moves a file to the system trash',
   'A command that renames a file in place',
   'A command that hides a file from listings'
 ]::text[],
 '___ the old build folder before you run a fresh install.',
 'Use ''rm'' in a sentence about deleting a file from the terminal.',
 'curated', 'curator', '2026-05-04'),

('cli-manpage', 'man (manpage)', 'man page', 'git-cli', 1,
 'The built-in manual for a command-line tool — type `man <command>` to read it.',
 'A manpage (short for manual page) is documentation that ships with most UNIX tools. Run `man ls` and you get a screenful explaining every flag, every option, every quirk. It''s how developers look things up offline before there was Stack Overflow, and it still works.',
 'Check the man page for grep — there''s a flag to ignore case if you want it.',
 'When Claude Code or dev family says "RTFM" or "the man page covers it," this is what they''re pointing at. Knowing it exists means you have a built-in answer for "what does this flag do?" on your own machine.',
 ARRAY['cli-bash','cli-grep','cli-terminal']::text[],
 ARRAY['cli-terminal','cli-bash']::text[],
 null,
 ARRAY[
   'A README file packaged with a tool',
   'A help message printed when a command errors',
   'A wiki page hosted on GitHub'
 ]::text[],
 'Check the ___ for grep — there''s a flag to ignore case if you want it.',
 'Use ''man page'' in a sentence about reading the built-in docs for a command.',
 'curated', 'curator', '2026-05-04');

-- ────────────────────────────────────────────────────────────
-- Stage B3 — 27 more curated anchor terms for the dev-concepts path
-- All difficulty 1, all curated, reviewed 2026-05-04.
-- Voice matches the git-commit / dev-readme template above.
-- Local seed equivalent of supabase/migrations/20260504100000_more_anchors_dev_concepts.sql.
-- dev-server / dev-client are CONCEPTUAL ("what is a server", "what is a client")
-- vs. the systems sys-server (a specific machine running an application). The
-- long_definitions name this distinction explicitly.
-- ────────────────────────────────────────────────────────────

insert into terms (
  id, term, pronunciation, path, difficulty,
  one_line_definition, long_definition, example_in_sentence, why_it_matters,
  related_terms, prerequisites, stretch_term,
  multiple_choice_distractors, fill_in_blank_sentence, use_in_sentence_prompt,
  source, reviewed_by, reviewed_at
) values

-- ─── dev-concepts: codebase shape (3) ─────────────────────────
('dev-repo', 'repository', 'repo', 'dev-concepts', 1,
 'A folder of code tracked by Git, with all of its history and branches in one place.',
 'A repository (almost always shortened to "repo") is the unit of a project in version control. It holds every file, every commit, every branch — the entire history of how the code got the way it is. A repo can live just on your laptop, but most teams sync them to a hosting service like GitHub.',
 'I cloned the repo last night and the README walks through setup pretty cleanly.',
 'Every Claude Code session opens inside a repo. When dev family says "send me the repo" or "is it on the same repo?" they mean this folder-plus-history bundle. Hearing repo and thinking "the project" makes most build conversations land.',
 ARRAY['git-clone','git-commit','dev-readme']::text[],
 ARRAY[]::text[],
 'git-fork',
 ARRAY[
   'A backup of a single source code file',
   'A live deployment of a web application',
   'A folder of compiled binaries ready to ship'
 ]::text[],
 'I cloned the ___ last night and the README walks through setup pretty cleanly.',
 'Use ''repo'' or ''repository'' in a sentence about a project tracked in version control.',
 'curated', 'curator', '2026-05-04'),

('dev-endpoint', 'endpoint', null, 'dev-concepts', 1,
 'A specific URL that an API exposes for one kind of request.',
 'An endpoint is a single address inside an API — `/users` to get users, `/login` to log in, `/orders/123` to fetch one order. Each endpoint accepts certain requests and returns certain responses. An API is really just a bundle of endpoints with a shared base URL.',
 'The /users endpoint returns 401 if the token is missing — that''s why the app is blank.',
 'Every "the API is broken" debugging conversation eventually narrows down to "which endpoint?" Knowing the term means you can talk about a specific URL on a specific service without losing precision.',
 ARRAY['dev-api','sys-rest','dev-backend']::text[],
 ARRAY['dev-api']::text[],
 null,
 ARRAY[
   'A page of an app a user can visit',
   'A device connected to a corporate network',
   'A point on a chart showing the latest data'
 ]::text[],
 'The /users ___ returns 401 if the token is missing — that''s why the app is blank.',
 'Use ''endpoint'' in a sentence about one specific URL on an API.',
 'curated', 'curator', '2026-05-04'),

('dev-frontend', 'frontend', null, 'dev-concepts', 1,
 'The part of an app that a user actually sees and interacts with — usually in a browser or on a phone.',
 'The frontend is everything that runs on the user''s device: buttons, screens, layouts, animations. React, Vue, and Swift UI are frontend frameworks. The frontend talks to the backend to get data and save changes, but the visual surface itself is its own world of code.',
 'The frontend is fine — the spinner just means the backend is taking forever to respond.',
 'Every Catalyst and side reaction app you build is mostly frontend code. When dev family asks "is the bug frontend or backend?" they''re narrowing down which half of the system to look at — fluency here cuts the search space in half.',
 ARRAY['dev-backend','dev-client','dev-framework']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'The first screen a user sees when launching an app',
   'A storefront page on an e-commerce site',
   'The marketing website for a software product'
 ]::text[],
 'The ___ is fine — the spinner just means the backend is taking forever to respond.',
 'Use ''frontend'' in a sentence about the visible part of an app.',
 'curated', 'curator', '2026-05-04'),

-- ─── dev-concepts: client/server roles (4) ────────────────────
('dev-backend', 'backend', null, 'dev-concepts', 1,
 'The part of an app that runs on a server — handling data, auth, and business logic out of sight of the user.',
 'The backend is everything the user doesn''t see directly: the database, the API, the auth checks, the scheduled jobs. When the frontend taps a button, the backend is what answers. Supabase is a backend; so is a custom Node server, a Rails app, or a Python API.',
 'I''ll wire the backend up to send the email — the frontend just needs to fire the request.',
 'Most "why doesn''t this work?" answers eventually point at the backend. Knowing the term lets you have precise conversations about where data lives, who can touch it, and why a request failed.',
 ARRAY['dev-frontend','dev-server','dev-database']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'The settings menu of an app',
   'A dashboard that admins use to manage users',
   'The codebase that handles user interface design'
 ]::text[],
 'I''ll wire the ___ up to send the email — the frontend just needs to fire the request.',
 'Use ''backend'' in a sentence about the server-side half of an app.',
 'curated', 'curator', '2026-05-04'),

('dev-server', 'server (concept)', null, 'dev-concepts', 1,
 'In the client/server model, the side that waits for requests and sends back responses.',
 'As a concept, "server" is a role: the program (or computer) that other programs call into. It''s the listener in the conversation. This is distinct from the systems sense of server (a specific machine you SSH into) — here, server just means "whichever side is being asked, not the side doing the asking."',
 'In a request/response model, the server is whoever responds — your phone is the client.',
 'Every API conversation assumes you understand the role of "server" in the abstract. Knowing the conceptual server (a role) vs. a specific machine makes architecture talk much easier to follow.',
 ARRAY['dev-client','dev-backend','sys-server']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A waiter at a restaurant who takes orders',
   'The fastest computer on a local network',
   'A program that runs only when a user clicks a button'
 ]::text[],
 'In a request/response model, the ___ is whoever responds — your phone is the client.',
 'Use ''server'' in a sentence about the side that responds to requests.',
 'curated', 'curator', '2026-05-04'),

('dev-client', 'client', null, 'dev-concepts', 1,
 'In the client/server model, the side that initiates a request and waits for a response.',
 'A client is whatever asks. Your phone is a client when it loads a webpage. Your browser is a client to the web server. The Anthropic SDK in Jargon is a client to the Anthropic API. Anything that says "give me this" is acting as a client in that moment.',
 'The mobile app is a client — every screen is asking the backend for data.',
 'When you read "the client sends a request" in API docs or hear "is it a client-side bug?" in a debug session, this is the role being talked about. Knowing the pair (client asks, server answers) unlocks how every networked app is wired.',
 ARRAY['dev-server','dev-frontend','dev-api']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A paying customer of a software company',
   'A team member assigned to write client documentation',
   'A spreadsheet shared between two people'
 ]::text[],
 'The mobile app is a ___ — every screen is asking the backend for data.',
 'Use ''client'' in a sentence about the side that asks for data.',
 'curated', 'curator', '2026-05-04'),

('dev-database', 'database (concept)', null, 'dev-concepts', 1,
 'The system of record for an app — where the data that has to outlive a single session lives.',
 'As a concept, the database is the persistent memory of an app. When you sign up, your account row gets written there. When you log in, the auth check reads from there. Without a database, every app would forget you the moment you closed it. (Distinct from the systems entry sys-database, which goes deeper into Postgres-style table mechanics.)',
 'Anything we want to remember across sessions has to live in the database, not in app state.',
 'Most app architecture conversations start with "where does the data live?" Knowing what a database IS — a permanent place to keep data — makes that question a clear starting point instead of a vague one.',
 ARRAY['dev-backend','sys-database','dev-server']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A list of contacts saved in a phone app',
   'A folder of backup files on an external drive',
   'A read-only document explaining the project schema'
 ]::text[],
 'Anything we want to remember across sessions has to live in the ___, not in app state.',
 'Use ''database'' in a sentence about where an app keeps its persistent data.',
 'curated', 'curator', '2026-05-04'),

-- ─── dev-concepts: code reuse (4) ─────────────────────────────
('dev-framework', 'framework', null, 'dev-concepts', 1,
 'A pre-built skeleton for an app — it dictates the structure and you fill in the specifics.',
 'A framework gives you the bones of an app: routing, state management, lifecycle hooks, conventions for where things go. React, Vue, Rails, Django, Next.js — all frameworks. The tradeoff is power for opinion: a framework saves you weeks but makes you do things its way.',
 'We picked Vite + React as the framework so the build pipeline came mostly for free.',
 'Every Jargon, Catalyst, and side reaction app sits on top of a framework (React + Vite). Knowing the term means you can read tutorials and pick the right tool for a job without confusing it with a library.',
 ARRAY['dev-library','dev-dependency','dev-frontend']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A small reusable function imported into your code',
   'A design system used to style components',
   'A test runner that executes your test files'
 ]::text[],
 'We picked Vite + React as the ___ so the build pipeline came mostly for free.',
 'Use ''framework'' in a sentence about the structural foundation of an app.',
 'curated', 'curator', '2026-05-04'),

('dev-library', 'library', null, 'dev-concepts', 1,
 'A bundle of pre-written code you call into when you need it — it doesn''t dictate your app''s structure.',
 'A library is something YOU call. Lodash, date-fns, Zustand — you import a function or a class, use it, and your code keeps the steering wheel. That''s the difference from a framework, which calls YOU. (Hollywood Principle: a library you call, a framework calls you.)',
 'I''m going to add a date library so we''re not hand-rolling timezone math.',
 'Almost every install you''ll do via npm is a library. Recognizing the difference between library (a tool you reach for) and framework (a structure you live inside) is the foundation for "should I add this dependency?" decisions.',
 ARRAY['dev-framework','dev-dependency','dev-package-manager']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A read-only reference of code examples',
   'A folder of documentation for an open-source project',
   'A platform that hosts your application code'
 ]::text[],
 'I''m going to add a date ___ so we''re not hand-rolling timezone math.',
 'Use ''library'' in a sentence about pulling in pre-written code for one specific job.',
 'curated', 'curator', '2026-05-04'),

('dev-dependency', 'dependency', null, 'dev-concepts', 1,
 'A piece of outside code your project relies on to work — usually a library installed via a package manager.',
 'Dependencies are the libraries (and their libraries, and so on) that your project needs to run. They''re listed in a manifest like `package.json` and installed into a folder like `node_modules`. Adding one is a tradeoff: you save time, but you take on whatever bugs and updates that code carries forever.',
 'Every dependency we add is one more thing to keep updated and one more thing that can break.',
 'When Claude Code says "I''m adding this as a dependency" or dev family asks "what are your dependencies?" they''re asking about the outside code your project leans on. Fluency here is what powers "should we even add this?" judgment.',
 ARRAY['dev-library','dev-package-manager','dev-framework']::text[],
 ARRAY['dev-library']::text[],
 null,
 ARRAY[
   'A required field on a form',
   'A user permission needed to run an action',
   'A test that another test relies on running first'
 ]::text[],
 'Every ___ we add is one more thing to keep updated and one more thing that can break.',
 'Use ''dependency'' in a sentence about a library your project pulls in.',
 'curated', 'curator', '2026-05-04'),

('dev-package-manager', 'package manager', null, 'dev-concepts', 1,
 'A tool that installs, updates, and removes the libraries your project depends on.',
 'A package manager (npm, yarn, pnpm for JavaScript; pip for Python; brew for macOS apps) reads a manifest file, figures out everything your project needs, and downloads it from a central registry. It also keeps a lockfile so every machine ends up with the exact same versions.',
 'Run the package manager after you pull — there are new dependencies in package.json.',
 'Every "I cloned the repo but it won''t run" answer is usually "did you run the package manager?" Knowing the term means you understand the install step that bridges fresh code and a working app.',
 ARRAY['dev-dependency','dev-library','dev-build']::text[],
 ARRAY['dev-dependency']::text[],
 null,
 ARRAY[
   'A program that organizes shipping containers',
   'A tool that compresses your code for production',
   'A service that hosts your dependencies on the cloud'
 ]::text[],
 'Run the ___ after you pull — there are new dependencies in package.json.',
 'Use ''package manager'' in a sentence about installing your project''s dependencies.',
 'curated', 'curator', '2026-05-04'),

-- ─── dev-concepts: local environment (3) ──────────────────────
('dev-env-variable', 'environment variable', 'env var', 'dev-concepts', 1,
 'A named value held outside your code — usually for secrets, URLs, or settings that change per environment.',
 'Environment variables (env vars) live alongside the code, not inside it. Things like API keys, database URLs, and feature flags get stored as env vars so the same code can run with different settings in dev, staging, and production. They''re also how you keep secrets out of Git.',
 'Put the Supabase key in an env var so we don''t commit it to the repo by accident.',
 'Every secret leak you have ever read about started with someone hardcoding a value that should have been an env var. Knowing the term means you understand both safety AND why "it works locally but not in production" usually means a missing env var.',
 ARRAY['dev-localhost','dev-staging','dev-deploy']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A constant defined at the top of a JavaScript file',
   'A configuration setting saved inside a database row',
   'A flag passed when calling a function'
 ]::text[],
 'Put the Supabase key in an ___ so we don''t commit it to the repo by accident.',
 'Use ''environment variable'' in a sentence about storing a secret outside your code.',
 'curated', 'curator', '2026-05-04'),

('dev-localhost', 'localhost', 'LOH-cul-host', 'dev-concepts', 1,
 'The address that always points to your own machine — used for running and testing apps locally.',
 '`localhost` (also written as `127.0.0.1`) means "this computer." When you run a dev server it usually listens on localhost so only your machine can reach it. URLs like `http://localhost:5173` mean "the app running on this laptop, on port 5173" — invisible to anyone else.',
 'The dev server is up at localhost:5173 — open it in Safari to test the touch targets.',
 'Every "open it in your browser" instruction in a Claude Code session points to localhost. Knowing the term means you understand the difference between testing on your own machine and testing somewhere the public can reach.',
 ARRAY['dev-port','dev-server','dev-staging']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A file path on the local filesystem',
   'A nickname for the production environment',
   'The name of the user logged into the operating system'
 ]::text[],
 'The dev server is up at ___:5173 — open it in Safari to test the touch targets.',
 'Use ''localhost'' in a sentence about an app running on your own computer.',
 'curated', 'curator', '2026-05-04'),

('dev-port', 'port', null, 'dev-concepts', 1,
 'A numbered channel on a computer that lets multiple programs share a network address without colliding.',
 'A port is like an apartment number in a building. The address (`localhost`) is the building; the port (`5173`, `3000`, `54321`) tells the network which program inside to deliver the request to. That''s how you can run a Vite dev server on 5173 and a Supabase server on 54321 at the same time without confusion.',
 'The other dev server is already on port 3000 — we''ll need to move one of them.',
 'Every "address already in use" error is a port collision. Recognizing port numbers in URLs and error messages means you can untangle "two things fighting for the same channel" in seconds.',
 ARRAY['dev-localhost','dev-server']::text[],
 ARRAY['dev-localhost']::text[],
 null,
 ARRAY[
   'A USB connector on the side of a laptop',
   'A version of a software product for a different platform',
   'A folder where downloaded files are stored'
 ]::text[],
 'The other dev server is already on ___ 3000 — we''ll need to move one of them.',
 'Use ''port'' in a sentence about which network channel an app is running on.',
 'curated', 'curator', '2026-05-04'),

-- ─── dev-concepts: build & ship (5) ───────────────────────────
('dev-build', 'build', null, 'dev-concepts', 1,
 'The packaged, optimized output of your source code — what you actually deploy.',
 'A build takes your raw source files (TypeScript, JSX, CSS, images) and runs them through a tool like Vite or webpack that bundles, minifies, and optimizes everything into a folder of static assets. The build is what gets uploaded to a server, never the source.',
 'The build failed because we forgot to install the new dependency on CI.',
 'Every deploy starts with a build. When Claude Code says "the build is broken" or "the build is clean," they''re reporting on the step that turns your code into something a server can actually serve.',
 ARRAY['dev-deploy','dev-package-manager','dev-ci-cd']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'The act of writing the first version of an app',
   'A user interface mockup made by a designer',
   'A meeting where the team plans the next feature'
 ]::text[],
 'The ___ failed because we forgot to install the new dependency on CI.',
 'Use ''build'' in a sentence about the packaged output of your source code.',
 'curated', 'curator', '2026-05-04'),

('dev-ship', 'ship', null, 'dev-concepts', 1,
 'To get a feature into users'' hands — usually by deploying the build to production.',
 'Ship is the verb every dev uses for "we''re done, it''s out there." It''s lighter than "deploy" (which is the technical action) and broader — you can ship a feature, ship a fix, ship an entire app. The opposite is "blocked" or "still in review."',
 'I want to ship the streak fix today so users on a Friday-night streak don''t lose it.',
 'Some teams live by "ship polished tools, never MVPs" — ship is the word for the moment work crosses from "in progress" to "real for users." Hearing it in standup or in Claude Code makes the cadence of release talk land naturally.',
 ARRAY['dev-deploy','dev-build','dev-staging']::text[],
 ARRAY['dev-deploy']::text[],
 null,
 ARRAY[
   'Boxing up software on physical media to mail to customers',
   'Demoing a feature to stakeholders before release',
   'Filing a ticket asking another team to release something'
 ]::text[],
 'I want to ___ the streak fix today so users on a Friday-night streak don''t lose it.',
 'Use ''ship'' in a sentence about getting a feature in front of users.',
 'curated', 'curator', '2026-05-04'),

('dev-staging', 'staging vs production', null, 'dev-concepts', 1,
 'Two parallel deployments of your app — staging is for final testing, production is the live version users see.',
 'Most teams keep at least two environments. Staging is a near-identical copy of production where the team tests builds before users see them. Production (often shortened to "prod") is the real thing — the version a customer hits when they open the app. The cardinal sin is shipping to prod without checking staging first.',
 'I''ll deploy to staging tonight and check it on the iPhone 14 before pushing to prod tomorrow.',
 'Every grown-up release process has a staging step. When dev family says "is it on staging or prod?" they''re asking how cooked it is — knowing the pair makes you fluent in release-readiness conversations.',
 ARRAY['dev-deploy','dev-ship','dev-env-variable']::text[],
 ARRAY['dev-deploy']::text[],
 'dev-feature-flag',
 ARRAY[
   'A development branch and a release branch',
   'A test runner and a build runner',
   'A debug log and a production log'
 ]::text[],
 'I''ll deploy to ___ tonight and check it on the iPhone 14 before pushing to prod tomorrow.',
 'Use ''staging'' or ''production'' in a sentence about where your app is currently deployed.',
 'curated', 'curator', '2026-05-04'),

('dev-ci-cd', 'CI/CD', 'C-I-C-D', 'dev-concepts', 1,
 'Automated pipelines that test your code on every push and ship it when the tests pass.',
 'CI (Continuous Integration) means every commit triggers an automated run of your tests and build. CD (Continuous Deployment, or Continuous Delivery) means a passing CI run automatically deploys to staging — sometimes even straight to production. GitHub Actions, Vercel, and Netlify all run CI/CD pipelines.',
 'CI just went red — the new test is failing on Node 18 but passing locally on 20.',
 'Every "is the build green?" or "did CI pass?" question in tech orgs is about CI/CD. Knowing the term means you can read pipeline status badges and understand why a PR is or isn''t mergeable yet.',
 ARRAY['dev-build','dev-deploy','dev-unit-test']::text[],
 ARRAY['dev-build']::text[],
 null,
 ARRAY[
   'A coding style enforcement system',
   'A two-person code review process',
   'A scheduled rotation of who handles bugs'
 ]::text[],
 '___ just went red — the new test is failing on Node 18 but passing locally on 20.',
 'Use ''CI/CD'' in a sentence about an automated test-and-deploy pipeline.',
 'curated', 'curator', '2026-05-04'),

('dev-unit-test', 'unit test', null, 'dev-concepts', 1,
 'A small automated test that checks one piece of code in isolation.',
 'A unit test takes a single function (or a single component) and verifies it does what it''s supposed to with a few specific inputs. The "unit" is small on purpose — when a unit test fails, you know exactly which piece broke. Vitest and Jest are common unit-test runners for JS/TS.',
 'I''ll add a unit test for the streak math so we catch any timezone regressions early.',
 'Every Jargon test in `src/lib/__tests__/` is a unit test. Knowing the term separates "tests one small thing" (unit) from "tests how things work together" (integration) — the most common test-talk distinction.',
 ARRAY['dev-integration-test','dev-bug','dev-ci-cd']::text[],
 ARRAY[]::text[],
 'dev-integration-test',
 ARRAY[
   'A manual test performed by a human tester',
   'A performance test that measures app speed',
   'A test that runs the entire app end to end'
 ]::text[],
 'I''ll add a ___ for the streak math so we catch any timezone regressions early.',
 'Use ''unit test'' in a sentence about checking one small piece of code automatically.',
 'curated', 'curator', '2026-05-04'),

('dev-integration-test', 'integration test', null, 'dev-concepts', 1,
 'An automated test that exercises several pieces working together — usually slower and broader than a unit test.',
 'An integration test stitches multiple parts of your code together (or hits a real database, or talks to a real API) to verify they cooperate. They catch bugs that unit tests miss — the ones that only show up when two correct pieces meet — but they take longer and break more easily as the system changes.',
 'The unit tests pass but the integration test caught a bug at the auth/database boundary.',
 'When dev family says "the integration suite is flaky" or Claude Code differentiates "unit" from "integration" tests, knowing the term clarifies which level of confidence you''re currently at.',
 ARRAY['dev-unit-test','dev-bug','dev-ci-cd']::text[],
 ARRAY['dev-unit-test']::text[],
 null,
 ARRAY[
   'A test of how two designers'' mockups merge together',
   'A test that runs only on the production database',
   'A test that measures how long your app takes to start'
 ]::text[],
 'The unit tests pass but the ___ caught a bug at the auth/database boundary.',
 'Use ''integration test'' in a sentence about testing how multiple parts of an app work together.',
 'curated', 'curator', '2026-05-04'),

-- ─── dev-concepts: bugs & maintenance (5) ─────────────────────
('dev-bug', 'bug', null, 'dev-concepts', 1,
 'A defect in code that causes the app to behave incorrectly.',
 'A bug is anything the code does that it''s not supposed to do — a wrong calculation, a button that doesn''t respond, a layout that breaks on iPhone. The term comes from a literal moth jammed in an early computer in 1947. Most engineering work is split between adding features and squashing bugs.',
 'I just hit a bug where the streak resets at the wrong hour — going to investigate now.',
 'Bug is the universal word for "something is broken." When you log a JIRA ticket as a bug, when Claude Code says "I see a bug here," when dev family asks "is that a bug or a feature?" — same word, same idea. Foundational vocabulary.',
 ARRAY['dev-issue-ticket','dev-unit-test','dev-refactor']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'A new feature requested by a user',
   'A small icon used in an interface',
   'A planned interruption for system maintenance'
 ]::text[],
 'I just hit a ___ where the streak resets at the wrong hour — going to investigate now.',
 'Use ''bug'' in a sentence about something not working right in code.',
 'curated', 'curator', '2026-05-04'),

('dev-issue-ticket', 'issue / ticket', null, 'dev-concepts', 1,
 'A tracked record of one piece of work — a bug to fix, a feature to build, or a chore to handle.',
 '"Issue" is what GitHub and most open-source tools call a tracked piece of work. "Ticket" is what JIRA and most enterprise tools call the same thing. Both are the same idea: a single line item with a title, description, assignee, and status that the team can talk about and track to completion.',
 'Open an issue on the repo with the screenshot so I don''t lose track of it.',
 'Every piece of engineering work eventually becomes an issue or a ticket somewhere. Knowing they''re the same idea (issue = ticket = one bounded chunk of work) means you can navigate any team''s tracker without re-learning the vocabulary.',
 ARRAY['agile-ticket','ent-jira','dev-bug']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'An invoice for software services',
   'A merge request awaiting review',
   'A monitoring alert from a server'
 ]::text[],
 'Open an ___ on the repo with the screenshot so I don''t lose track of it.',
 'Use ''issue'' or ''ticket'' in a sentence about tracking one piece of work.',
 'curated', 'curator', '2026-05-04'),

('dev-mvp', 'MVP', 'M-V-P', 'dev-concepts', 1,
 'Minimum Viable Product — the smallest version of an app that delivers core value, shipped to learn from real users.',
 'MVP is the strip-it-down philosophy: build the least amount of product you can get away with, ship it, see what real users do, iterate. The opposite of a polished launch. One common rule is "ship polished tools, never MVPs" — but the term shows up everywhere in startup and tech-family conversations.',
 'They''re calling this v0.1 release an MVP so they can learn from real usage before adding more.',
 'When dev family or a tech podcast says "we shipped an MVP," they mean "barely-there but in users'' hands." Knowing the term means you understand the cultural philosophy you''re reacting against — and can explain why your work doesn''t look like one.',
 ARRAY['dev-ship','dev-feature-flag','dev-refactor']::text[],
 ARRAY['dev-ship']::text[],
 null,
 ARRAY[
   'Most Valuable Programmer — a top-performing engineer',
   'A staging copy of an app reserved for QA',
   'A pricing tier with the smallest feature set'
 ]::text[],
 'They''re calling this v0.1 release an ___ so they can learn from real usage before adding more.',
 'Use ''MVP'' in a sentence about a stripped-down first version of a product.',
 'curated', 'curator', '2026-05-04'),

('dev-refactor', 'refactor', null, 'dev-concepts', 1,
 'Rewriting how code is built without changing what it does — like reorganizing a workflow without changing the output.',
 'A refactor restructures the inside of a piece of code (clearer names, fewer files, less duplication, better abstractions) while keeping the external behavior identical. Done well, the user notices nothing — but the next change becomes easier. Done badly, you introduce bugs while telling yourself you weren''t.',
 'Let''s refactor the lesson engine before we add the new SRS rules — it''s getting hard to read.',
 'When Claude Code says "I''m going to refactor this" or dev family asks "is this a refactor or a feature?" they''re drawing the line between "shape change" and "behavior change." Knowing the term keeps you on the right side of that distinction.',
 ARRAY['dev-bug','dev-tech-debt','dev-legacy']::text[],
 ARRAY[]::text[],
 null,
 ARRAY[
   'Adding a new feature requested by users',
   'Reverting a commit that introduced a bug',
   'Translating an app into a new spoken language'
 ]::text[],
 'Let''s ___ the lesson engine before we add the new SRS rules — it''s getting hard to read.',
 'Use ''refactor'' in a sentence about rewriting code without changing what it does.',
 'curated', 'curator', '2026-05-04'),

('dev-legacy', 'legacy code', null, 'dev-concepts', 1,
 'Older code that''s still running in production — usually inherited, often poorly understood, expensive to change.',
 'Legacy code is anything the team is afraid to touch: old enough that the original authors are gone, important enough that you can''t delete it, fragile enough that small changes break it in surprising places. Most enterprise codebases (large enterprise systems included) are mostly legacy, with new features built carefully on top.',
 'Half the migration is wading through legacy code from before the rewrite in 2018.',
 'Anything older than a few years in a big company becomes legacy. When dev family complains about "the legacy auth system" or "I''ve been stuck in legacy all week," knowing the term gives the complaint texture: it''s old, dangerous, and slow to change.',
 ARRAY['dev-tech-debt','dev-refactor','dev-bug']::text[],
 ARRAY[]::text[],
 'dev-tech-debt',
 ARRAY[
   'Code written by a junior developer that needs review',
